export function stableStringify(value) {
    if (value === null || typeof value !== "object") {
        return JSON.stringify(value);
    }
    if (Array.isArray(value)) {
        return `[${value.map((item) => stableStringify(item)).join(",")}]`;
    }
    const obj = value;
    return `{${Object.keys(obj)
        .sort()
        .map((key) => `${JSON.stringify(key)}:${stableStringify(obj[key])}`)
        .join(",")}}`;
}
export function normalizeToolCallInputForIdentity(input) {
    if (input && typeof input === "object" && !Array.isArray(input)) {
        return input;
    }
    return { rawInput: input };
}
export function parseToolInputForIdentity(input) {
    if (typeof input !== "string")
        return input;
    try {
        return JSON.parse(input);
    }
    catch {
        return input;
    }
}
export function toolPairKey(toolName, input) {
    return `${toolName}:${stableStringify(normalizeToolCallInputForIdentity(parseToolInputForIdentity(input)))}`;
}
